const body=document.body,banner=document.querySelector('.banner'),empty=document.querySelector('.empty');
const copy={importing:['Importing attachment: release-evidence.pdf 62%.','normal'],oversize:['Attachment rejected. It is over the 25 MB limit.','error'],generating:['Generating the Quality Control artifact locally.','normal'],success:['Artifact generated successfully and placed in Artifacts.','normal'],failure:['Provider failure: OpenAI returned a definite authentication error.','error'],unknown:['Outcome unknown: request may have reached the provider. Automatic replay is disabled.','warning'],cancelled:['Session operation cancelled.','normal']};
function notify(text,kind='normal'){banner.textContent=text;banner.dataset.kind=kind;banner.hidden=false}function state(value){body.dataset.state=value;empty.hidden=value!=='empty';document.querySelector('.session-head').hidden=value==='empty';document.querySelector('.telemetry').hidden=value==='empty';document.querySelector('.split').hidden=value==='empty';if(copy[value])notify(...copy[value]);else banner.hidden=true}
document.querySelector('#state').addEventListener('change',e=>state(e.target.value));document.querySelectorAll('[data-screen-button]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.screenButton;body.dataset.screen=id;document.querySelectorAll('.stage,.screen').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('selected',x.dataset.screenButton===id))}));document.querySelectorAll('[data-dialog]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.dialog).showModal()));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{let a=b.dataset.action;if(a==='generate')state('generating');if(a==='cancel')state('cancelled');if(a==='pause')notify('Session paused. Continue is available in the real application.');if(a==='copy')notify('Transcript copied in this demonstration.');if(a==='send')notify('Guidance queued for the next phase.');if(a==='import')state('importing')}));document.querySelector('#new').addEventListener('close',()=>{if(document.querySelector('#new').returnValue==='default'){state('new');notify('New meeting table created with fake data.')}});
